        grid[x][y] = z

    # Initialize DP arrays for both paths
    dp1 = [[0] * N for _ in range(N)]
    dp2 = [[0] * N for _ in range(N)]

    # Compute the maximum sum for the first path
    for x in range(N):
        for y in range(N):
            if x == 0 and y == 0:
                dp1[x][y] = grid[x][y]
            else:
                dp1[x][y] = max(dp1[x-1][y], dp1[x][y-1]) + grid[x][y]

    # Compute the maximum sum for the second path
    for x in range(N-1, -1, -1):
        for y in range(N-1, -1, -1):
            if x == N-1 and y == N-1:
                dp2[x][y] = grid[x][y]
            else:
                dp2[x][y] = max(dp2[x+1][y], dp2[x][y+1]) + grid[x][y]

