def cantor_numbering(N: int) -> str:
    if N == 1:
        return "1/1"
    height = floor(log2(N))
    x, y = N - 2**(height+1) + 1, 1
    teleport_pole = 0
    for i in range(1, height+1):
        if i == 1:
            teleport_pole = x*(i+1)
            continue
        if i == height:
            teleport_pole = x*(height+1)
            break
        if numpy.log2(teleport_pole) == numpy.log2(x*(i+1)*y):
            teleport_pole = x*(i+1)
            break
    denominator = x
    numerator = N - teleport_pole
    return f"{numerator}/{denominator}"

