        factorial reverses[i] = pow(factorials[i], -1, 10**6 + 7)

    mod = 10**9 + 7

    def choose(n, k):
        return (factorials[n] * factorial reverses[k]) % mod * ((factorials[n - k] * factorial reverses[n - k]) % mod) * mod

