def min_groups(w, n, prices):
    def ncr(n, r):
        """Calculate the binomial coefficient (n choose r)."""
        if r > n // 2:
            r = n - r
        result = 1
        for i in range(r):
            result = result * (n - i) // (i + 1)
        return result

    num_groups = 0
    group_price = 0
    prices.sort(reverse=True)

    while prices:
        if group_price + prices[0] <= w:
            group_price += prices.pop(0)
            num_groups += 1
        else:
            if len(prices) > 0:
                group_price -= ncr(len(prices) - 1, 1) * min(prices)
            else:
                break

    return num_groups

